package urbanmatch.controller;
import java.util.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import urbanmatch.repository.UserRepository;
import urbanmatch.entity.User;
@RestController @RequestMapping("/api")
public class ExtraController {
 private final NamedParameterJdbcTemplate db; private final UserRepository users;
 public ExtraController(NamedParameterJdbcTemplate db,UserRepository users){this.db=db;this.users=users;}
 private User me(Authentication a){return users.findByEmail(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private User role(Authentication a,String r){User u=me(a);if(!r.equals(u.role)||!"active".equals(u.status))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return u;}
 private MapSqlParameterSource p(Object... a){var x=new MapSqlParameterSource();for(int i=0;i<a.length;i+=2)x.addValue((String)a[i],a[i+1]);return x;}
 private List<Map<String,Object>> query(String sql,Object... params){return db.queryForList(sql,p(params));}
 private int exec(String sql,Object... params){return db.update(sql,p(params));}
 private void required(boolean ok){if(!ok)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not authorized");}
 private boolean exists(String sql,Object... params){return !query(sql,params).isEmpty();}
 @GetMapping("/profile") public Map<String,Object> profile(Authentication a){User u=me(a);return Map.of("id",u.id,"fullName",u.fullName,"email",u.email,"role",u.role,"status",u.status);}
 @PatchMapping("/profile") @Transactional public Map<String,Object> profileUpdate(Authentication a,@RequestBody Map<String,String> body){User u=me(a);String name=body.getOrDefault("fullName",u.fullName).trim();if(name.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name required");u.fullName=name;u.phone=body.getOrDefault("phone",u.phone);u.location=body.getOrDefault("location",u.location);users.save(u);return Map.of("id",u.id,"fullName",u.fullName,"email",u.email);}
 @GetMapping("/employer/profile") public List<Map<String,Object>> employerProfile(Authentication a){User u=role(a,"employer");return query("select * from employer_profiles where user_id=:u","u",u.id);}
 @PutMapping("/employer/profile") @Transactional public void employerProfileUpdate(Authentication a,@RequestBody Map<String,String> b){User u=role(a,"employer");String name=b.getOrDefault("companyName","").trim();if(name.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Company name required");int n=exec("update employer_profiles set company_name=:n,industry=:i,company_description=:d,website=:w where user_id=:u","n",name,"i",b.get("industry"),"d",b.get("companyDescription"),"w",b.get("website"),"u",u.id);if(n==0)exec("insert into employer_profiles(user_id,company_name,industry,company_description,website) values(:u,:n,:i,:d,:w)","u",u.id,"n",name,"i",b.get("industry"),"d",b.get("companyDescription"),"w",b.get("website"));}
 @GetMapping("/saved-jobs") public List<Map<String,Object>> saved(Authentication a){User u=role(a,"seeker");return query("select sj.id,sj.job_id,sj.saved_at from saved_jobs sj where sj.seeker_id=:u order by sj.saved_at desc","u",u.id);}
 @PostMapping("/saved-jobs/{jobId}") @Transactional public void save(Authentication a,@PathVariable Long jobId){User u=role(a,"seeker");required(exists("select id from jobs where id=:j and status='open'","j",jobId));exec("insert ignore into saved_jobs(seeker_id,job_id) values(:u,:j)","u",u.id,"j",jobId);}
 @DeleteMapping("/saved-jobs/{jobId}") public void unsave(Authentication a,@PathVariable Long jobId){User u=role(a,"seeker");exec("delete from saved_jobs where seeker_id=:u and job_id=:j","u",u.id,"j",jobId);}
 @GetMapping("/conversations") public List<Map<String,Object>> conversations(Authentication a){User u=me(a);return query("select * from conversations where seeker_id=:u or employer_id=:u order by updated_at desc","u",u.id);}
 @PostMapping("/conversations") public void conversation(Authentication a,@RequestBody Map<String,Long> b){User u=me(a);Long seeker=b.get("seekerId"),employer=b.get("employerId"),job=b.get("jobId");required(seeker!=null&&employer!=null&&(u.id.equals(seeker)||u.id.equals(employer)));required(exists("select id from users where id=:s and role='seeker'","s",seeker)&&exists("select id from users where id=:e and role='employer'","e",employer));if(job!=null)required(exists("select id from jobs where id=:j and employer_id=:e","j",job,"e",employer));if(!exists("select id from conversations where seeker_id=:s and employer_id=:e and (job_id <=> :j)","s",seeker,"e",employer,"j",job))exec("insert into conversations(seeker_id,employer_id,job_id) values(:s,:e,:j)","s",seeker,"e",employer,"j",job);}
 private void participant(User u,Long id){required(exists("select id from conversations where id=:c and (seeker_id=:u or employer_id=:u)","c",id,"u",u.id));}
 @GetMapping("/conversations/{id}/messages") public List<Map<String,Object>> messages(Authentication a,@PathVariable Long id){User u=me(a);participant(u,id);return query("select id,conversation_id,sender_id,message_text,is_read,sent_at from messages where conversation_id=:c order by sent_at","c",id);}
 @PostMapping("/conversations/{id}/messages") @Transactional public void send(Authentication a,@PathVariable Long id,@RequestBody Map<String,String> b){User u=me(a);participant(u,id);String msg=b.getOrDefault("message","").trim();if(msg.isEmpty()||msg.length()>5000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid message");exec("insert into messages(conversation_id,sender_id,message_text,is_read) values(:c,:u,:m,false)","c",id,"u",u.id,"m",msg);exec("update conversations set updated_at=current_timestamp where id=:c","c",id);
  List<Map<String,Object>> peers=query("select seeker_id,employer_id from conversations where id=:c","c",id);
  if(!peers.isEmpty()){Map<String,Object> row=peers.get(0);Long other=((Number)row.get("seeker_id")).longValue()==u.id.longValue()?((Number)row.get("employer_id")).longValue():((Number)row.get("seeker_id")).longValue();notifyUser(other,"New message","You have received a message.","message",id);}
 }
 @PatchMapping("/conversations/{id}/read") public void read(Authentication a,@PathVariable Long id){User u=me(a);participant(u,id);exec("update messages set is_read=true where conversation_id=:c and sender_id<>:u","c",id,"u",u.id);}
 private void notifyUser(Long uid,String title,String message,String type,Long relatedId){
  exec("insert into notifications(user_id,title,message,notification_type,related_id,is_read) values(:u,:t,:m,:k,:r,false)","u",uid,"t",title,"m",message,"k",type,"r",relatedId);
 }
 @GetMapping("/reviews") public List<Map<String,Object>> allReviews(){return query("select id,reviewer_id,reviewee_id,rating,comment,created_at from reviews order by created_at desc");}
 @GetMapping("/notifications") public List<Map<String,Object>> notifications(Authentication a){User u=me(a);return query("select * from notifications where user_id=:u order by created_at desc","u",u.id);}
 @PatchMapping("/notifications/{id}/read") public void notificationRead(Authentication a,@PathVariable Long id){User u=me(a);exec("update notifications set is_read=true where id=:id and user_id=:u","id",id,"u",u.id);}
 @GetMapping("/reviews/{userId}") public List<Map<String,Object>> reviews(@PathVariable Long userId){return query("select id,reviewer_id,reviewee_id,rating,comment,created_at from reviews where reviewee_id=:u","u",userId);}
 @PostMapping("/reviews") @Transactional public void review(Authentication a,@RequestBody Map<String,Object> b){User u=me(a);Long target=num(b.get("revieweeId"));int rating=((Number)b.getOrDefault("rating",0)).intValue();required(target!=null&&!target.equals(u.id)&&exists("select id from users where id=:u","u",target));if(rating<1||rating>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Rating must be 1-5");required(exists("select a.id from applications a join jobs j on j.id=a.job_id where a.status='accepted' and ((a.seeker_id=:u and j.employer_id=:t) or (a.seeker_id=:t and j.employer_id=:u))","u",u.id,"t",target));if(exists("select id from reviews where reviewer_id=:u and reviewee_id=:t","u",u.id,"t",target))throw new ResponseStatusException(HttpStatus.CONFLICT,"Already reviewed");exec("insert into reviews(reviewer_id,reviewee_id,rating,comment) values(:u,:t,:r,:c)","u",u.id,"t",target,"r",rating,"c",b.get("comment"));notifyUser(target,"New review","You received a new rating and review.","review",null);}
 private Long num(Object o){return o instanceof Number n?n.longValue():null;}
 @PostMapping("/reports") @Transactional public void report(Authentication a,@RequestBody Map<String,Object> b){User u=me(a);Long target=num(b.get("reportedUserId")),job=num(b.get("reportedJobId"));if((target==null)==(job==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Report exactly one target");String reason=String.valueOf(b.getOrDefault("reason","")).trim();if(reason.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reason required");if(target!=null)required(exists("select id from users where id=:u","u",target));if(job!=null)required(exists("select id from jobs where id=:j","j",job));exec("insert into reports(reporter_id,reported_user_id,reported_job_id,reason,description,status) values(:u,:t,:j,:r,:d,'pending')","u",u.id,"t",target,"j",job,"r",reason,"d",b.get("description"));}
 @PatchMapping("/applications/{id}/withdraw") @Transactional public void withdraw(Authentication a,@PathVariable Long id){User u=role(a,"seeker");int n=exec("update applications set status='withdrawn' where id=:id and seeker_id=:u and status='pending'","id",id,"u",u.id);if(n==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Application cannot be withdrawn");List<Map<String,Object>> rows=query("select j.employer_id,j.title from applications a join jobs j on j.id=a.job_id where a.id=:id","id",id);if(!rows.isEmpty())notifyUser(((Number)rows.get(0).get("employer_id")).longValue(),"Application withdrawn","An applicant withdrew from "+rows.get(0).get("title"),"application",id);}
 @GetMapping("/admin/reports") public List<Map<String,Object>> reports(Authentication a){role(a,"admin");return query("select * from reports order by created_at desc");}
 @PatchMapping("/admin/reports/{id}") public void reportStatus(Authentication a,@PathVariable Long id,@RequestParam String status){role(a,"admin");if(!List.of("pending","reviewed","resolved","dismissed").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);exec("update reports set status=:s where id=:id","s",status,"id",id);}
 @GetMapping("/admin/users") public List<Map<String,Object>> adminUsers(Authentication a){role(a,"admin");return query("select id,full_name,email,role,status,phone,location,created_at from users order by id desc");}
 @PatchMapping("/admin/users/{id}/status") public void userStatus(Authentication a,@PathVariable Long id,@RequestParam String status){User u=role(a,"admin");if(!List.of("active","suspended").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);required(!u.id.equals(id));exec("update users set status=:s where id=:id and role<>'admin'","s",status,"id",id);}
 @GetMapping("/admin/jobs") public List<Map<String,Object>> adminJobs(Authentication a){role(a,"admin");return query("select * from jobs order by created_at desc");}
 @PatchMapping("/admin/jobs/{id}/status") public void adminJobStatus(Authentication a,@PathVariable Long id,@RequestParam String status){role(a,"admin");if(!List.of("open","closed").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);exec("update jobs set status=:s where id=:id","s",status,"id",id);}
}
